// Every derived value must be a getter: a value captured in a closure freezes
// the field on the source it was built with and then writes to the wrong graph
// after a source switch.
import { Show, createEffect, createMemo, on } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  nameNode, nameCheck, expandIri, renameNode, renameQuads,
  renameCheck, nodePositions, nameSuggestion, setAction, setIri, termOptions,
} from '../../model/edit.js';
import { curie } from '../../model/parse.js';
import {
  DATE_DEFAULT, bearingPred, validIriText, termOf, setDisplayedLiteral,
} from '../../model/fields.js';
import type { Quad, Term } from '../../model-boundary.js';
import { graph, graphVersion } from '../../stores/corpus.js';
import {
  editSource as panelEditSource, sourceRows, makeEditable,
} from '../../stores/source-management.js';
import type { SourceEdit } from '../../stores/source-management.js';
import { currentLang, text, view, setRefusal } from '../../stores/view.js';
import { editFocus, focusAddress, requestEditFocus, clearFocusFor } from '../shared/edit-hook.jsx';
import { moveRememberedOpen } from '../list/card-list.jsx';
import type { FieldSpec } from './hooks.jsx';
import { core } from './core.js';
import { Button } from './button.jsx';
import { InlineField, IriCombobox, optionText } from './field.jsx';
import type { IriOption, FieldHook } from './field.jsx';
import { unlockExplanation, SlotIcon } from './strip.jsx';
import { PartyField } from './party-field.jsx';
import { showToast } from './toast.jsx';
import './edit.css';

interface ReadStore {
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

// A term from the worker carries only its `id`; a cast type-checks and then
// makes `getQuads` return zero quads.
const asTerm = (t: unknown): Term | null => termOf(t) as Term | null;

let optionCache: { g: unknown; v: number; options: Record<string, IriOption[]> } | null = null;

export function fieldOptions(category: string): IriOption[] {
  const g = graph();
  const v = graphVersion();
  if (!g) return [];
  if (!optionCache || optionCache.g !== g || optionCache.v !== v) {
    optionCache = { g, v, options: termOptions(g) as Record<string, IriOption[]> };
  }
  return optionCache.options[category] || [];
}

type State =
  | { kind: 'on' }
  | { kind: 'locked'; source: SourceEdit }
  | { kind: 'off'; reason: string };

function sourceOfGraph(graph: string): SourceEdit | null {
  if (!graph) return null;
  return sourceRows().find((b) => b.graph === graph && !b.fromSparql) || null;
}

export function fieldState(term: unknown, pred: string): State {
  const source = core().editSource();
  if (!source) return { kind: 'off', reason: text('edit.noEditSource') };
  const g = graph() as unknown as ReadStore | null;
  const t = asTerm(term);
  if (!g || !t || !pred) return { kind: 'off', reason: text('edit.fieldNoPath') };
  const own = g.getQuads(t, asTerm(pred), null, null);
  if (own.length) {
    if (core().quadsInEditSource(own)) return { kind: 'on' };
    const other = sourceOfGraph(((own[0].graph || {}) as { value?: string }).value || '');
    return other ? { kind: 'locked', source: other }
      : { kind: 'off', reason: text('edit.noEditSource') };
  }
  const node = g.getQuads(t, null, null, null);
  if (!node.length) return { kind: 'off', reason: text('edit.cardDerived') };
  const inSource = node.some((q) => ((q.graph || {}) as { value?: string }).value === source.graph);
  if (inSource) return { kind: 'on' };
  const other = sourceOfGraph(((node[0].graph || {}) as { value?: string }).value || '');
  return other ? { kind: 'locked', source: other }
    : { kind: 'off', reason: text('edit.noEditSource') };
}

function DimmedField(props: {
  state: State; read: () => JSX.Element; noPencil?: boolean;
}): JSX.Element {
  const locked = () => (props.state.kind === 'locked' ? props.state.source : null);
  const current = () => {
    const b = panelEditSource();
    return b ? (b.name || b.url || '') : '';
  };
  const title = () => {
    const b = locked();
    if (!b) return (props.state as { reason: string }).reason;
    return [text('edit.notEditSource'), unlockExplanation({
      name: b.name || b.url || b.graph,
      current: current() || undefined,
      warn: !b.opfs,
    })].join(' ');
  };
  const unlock = () => {
    const b = locked();
    if (b) void makeEditable(b).catch(() => {});
  };
  return (
    <span class="inline-field inline-field-locked">
      {props.read()}
      <Show when={!props.noPencil}>
        <span
          class={locked() ? 'edit-button inline-field-edit locked' : 'edit-button inline-field-edit action-off'}
          role="button"
          tabindex="0"
          title={title()}
          aria-label={title()}
          aria-disabled={locked() ? undefined : 'true'}
          on:click={(e: MouseEvent) => {
            if (!locked()) return;
            e.preventDefault();
            e.stopPropagation();
            unlock();
          }}
          on:keydown={(e: KeyboardEvent) => {
            if (!locked() || (e.key !== 'Enter' && e.key !== ' ')) return;
            e.preventDefault();
            e.stopPropagation();
            unlock();
          }}
        >
          ✎
          <SlotIcon />
        </span>
      </Show>
    </span>
  );
}

function acceptFocus(spec: FieldSpec, api: () => FieldHook | null): void {
  createEffect(on(editFocus, (address) => {
    if (!address || !spec.focusKey || address !== spec.focusKey) return;
    api()?.openEdit();
  }));
}

function reportOpened(spec: FieldSpec): void {
  if (spec.focusKey) clearFocusFor(spec.focusKey);
}

function carriesValue(term: unknown, pred: string): boolean {
  const g = graph() as unknown as ReadStore | null;
  const t = asTerm(term);
  if (!g || !t || !pred) return false;
  return g.getQuads(t, asTerm(pred), null, null).length > 0;
}

function TextField(props: {
  spec: FieldSpec; pred: () => string; read: () => JSX.Element;
}): JSX.Element {
  const own = () => {
    void graphVersion();
    return carriesValue(props.spec.term, props.pred());
  };
  const before = () => (props.spec.hint && !own() ? '' : (props.spec.value ?? ''));
  const empty = () => (props.spec.value ? props.read : undefined);
  let hook: FieldHook | null = null;
  acceptFocus(props.spec, () => hook);
  const fallbackShape = () => (props.spec.kind === 'date'
    ? DATE_DEFAULT : { lang: currentLang() });
  const save = (v: string) => {
    if (String(v) === before()) return;
    void core().execute(
      (f) => setDisplayedLiteral(f, f, props.spec.term, props.pred(), v, fallbackShape()),
      { group: true },
    );
  };
  return (
    <InlineField
      value={before()}
      multiline={props.spec.multiline}
      type={props.spec.kind === 'date' ? 'date' : 'text'}
      hint={props.spec.hint}
      empty={empty()}
      withoutPencil={props.spec.withoutPencil}
      onSave={save}
      onOpen={() => reportOpened(props.spec)}
      hook={(api) => { hook = api; }}
    />
  );
}

function IriField(props: {
  spec: FieldSpec; pred: () => string; read: () => JSX.Element;
}): JSX.Element {
  const options = createMemo(() => fieldOptions(props.spec.category || 'labeled'));
  let hook: FieldHook | null = null;
  acceptFocus(props.spec, () => hook);
  const startText = () => optionText(options(), props.spec.iri) || (props.spec.value ?? '');
  const startIri = (): string => {
    if (props.spec.iri) return props.spec.iri;
    const l = props.spec.value ?? '';
    const o = l ? options().find((x) => x.label === l) : null;
    return o ? o.iri : '';
  };
  let previous = startIri();
  const pickIri = (iri: string) => {
    if (iri && !validIriText(iri)) {
      setRefusal('edit.invalidIri', { input: iri });
      return;
    }
    if (iri === previous) return;
    previous = iri;
    const target = asTerm(props.spec.term);
    void core().execute(
      (f) => (props.spec.variant === 'action'
        ? setAction(f, target, iri) : setIri(f, target, props.pred(), iri)),
      { group: true },
    );
  };
  return (
    <IriCombobox
      options={options()}
      value={startText()}
      placeholder={props.spec.hint || undefined}
      onPick={pickIri}
      onOpen={() => reportOpened(props.spec)}
      hook={(api) => { hook = api; }}
    />
  );
}

export function nodeIriState(term: unknown): State {
  const source = core().editSource();
  if (!source) return { kind: 'off', reason: text('edit.noEditSource') };
  const g = graph() as unknown as ReadStore | null;
  const t = asTerm(term);
  if (!g || !t || (t.termType !== 'NamedNode' && t.termType !== 'BlankNode')) {
    return { kind: 'off', reason: text('edit.iriNoNode') };
  }
  const touched = t.termType === 'NamedNode'
    ? renameQuads(g, t.value) : nodePositions(g, t);
  if (!touched.length) return { kind: 'off', reason: text('edit.cardDerived') };
  if (core().quadsInEditSource(touched as never)) return { kind: 'on' };
  const other = sourceOfGraph(((touched[0].graph || {}) as { value?: string }).value || '');
  return other ? { kind: 'locked', source: other }
    : { kind: 'off', reason: text('edit.noEditSource') };
}

function NodeIriField(props: { spec: FieldSpec; state: State }): JSX.Element {
  const currentIri = () => String(props.spec.iri || '');
  const shown = () => {
    const c = curie(currentIri()) as string | null;
    return c && expandIri(c) === currentIri() ? c : currentIri();
  };
  const blank = () => {
    void graphVersion();
    return asTerm(props.spec.term)?.termType === 'BlankNode';
  };
  const proposal = () => {
    void graphVersion();
    return (nameSuggestion(graph(), props.spec.term) as string) || '';
  };
  // THE VERDICT BEFORE THE FIELD SHUTS. A refused name may never be shown as a
  // saved one, so the check runs where it can still keep the field open, and
  // hands back the sentence that then stands beside it.
  const check = (v: string): boolean | string => {
    const fresh = expandIri(String(v || '').trim()) as string;
    if (!fresh || fresh === currentIri()) return true;
    const verdict = (blank()
      ? nameCheck(graph(), props.spec.term, fresh)
      : renameCheck(graph(), currentIri(), fresh)) as { ok: boolean; reason?: string };
    if (verdict.ok) return true;
    const key = verdict.reason === 'taken' ? 'edit.iriTaken' : 'edit.invalidIri';
    setRefusal(key, { input: v });
    return text(key, { input: v });
  };

  const save = (v: string) => {
    const fresh = expandIri(String(v || '').trim()) as string;
    if (!fresh || fresh === currentIri()) return;
    const isBlank = blank();
    const was = isBlank ? String(asTerm(props.spec.term)?.value || '') : currentIri();
    const done = core().execute((f) => (isBlank
      ? nameNode(f, props.spec.term, fresh)
      : renameNode(f, currentIri(), fresh)), { group: true });
    // The node's address changes, and every fold keyed by it with it —
    // otherwise the card the author is working in folds shut under them.
    // Bookkeeping, so it rides with the WRITE and not with the rebuild that
    // follows: a rebuild that bounces still leaves the graph renamed.
    moveRememberedOpen(was, fresh);
    void done
      .then((ok) => { if (ok) showToast(isBlank ? 'edit.nodeNamed' : 'edit.nodeRenamed'); })
      .catch(() => {});
  };
  const readForm = () => (blank()
    ? <span class="inline-field-hint">{text('edit.iriGiveName')}</span>
    : <span class="inline-field-value">{shown()}</span>);
  return (
    <span
      class={blank() ? 'card-iri card-iri-blank' : 'card-iri mono'}
      title={blank() ? text('edit.iriGiveNameHint') : undefined}
    >
      <Show
        when={props.state.kind === 'on'}
        fallback={<DimmedField state={props.state} read={readForm} />}
      >
        <InlineField
          value={blank() ? '' : shown()}
          hint={blank() ? text('edit.iriGiveName') : undefined}
          startValue={blank() ? proposal() : undefined}
          validate={check}
          onSave={save}
        />
      </Show>
    </span>
  );
}

export function CardField(props: { spec: FieldSpec; read: () => JSX.Element }): JSX.Element {
  const pred = () => bearingPred(graph(), props.spec.term, [...props.spec.preds]);
  const isNodeIri = () => props.spec.variant === 'nodeIri';
  const state = (): State => {
    if (props.spec.notApplicable) return { kind: 'off', reason: props.spec.notApplicable };
    void graphVersion();
    return isNodeIri() ? nodeIriState(props.spec.term) : fieldState(props.spec.term, pred());
  };
  return (
    <Show when={view.editMode} fallback={props.read()}>
      <Show
        when={isNodeIri()}
        fallback={(
          <Show
            when={state().kind === 'on'}
            fallback={(
              <DimmedField
                state={state()}
                read={props.read}
                noPencil={props.spec.withoutPencil}
              />
            )}
          >
            <Show
              when={props.spec.kind === 'iri'}
              fallback={<TextField spec={props.spec} pred={pred} read={props.read} />}
            >
              <Show
                when={props.spec.variant === 'party'}
                fallback={<IriField spec={props.spec} pred={pred} read={props.read} />}
              >
                <PartyField spec={props.spec} pred={pred} read={props.read} />
              </Show>
            </Show>
          </Show>
        )}
      >
        <NodeIriField spec={props.spec} state={state()} />
      </Show>
    </Show>
  );
}
