import { createSignal } from 'solid-js';

// ONE open list at a time, and the KEY travels instead of a component ref: the
// button sits in the section heading and the list at the insertion place, two
// different spots in the tree that must agree without one owning the other.
const [openKey, setOpenKey] = createSignal<string | null>(null);

export { openKey };

export function reuseKey(cardKey: string, kind: string): string {
  return `${cardKey}|${kind}`;
}

export function toggleReuse(key: string): void {
  setOpenKey(openKey() === key ? null : key);
}

export function closeReuse(): void {
  setOpenKey(null);
}
