import { PREFIXES } from '../../../model/parse.js';
import { termOf as termFromJs } from '../../../model/term.js';
import type { Quad, Term } from '../../../model-boundary.js';

export const ODRL = PREFIXES.odrl as string;
const PROV = PREFIXES.prov as string;

export const NODE_PREDS = [
  `${ODRL}permission`, `${ODRL}prohibition`, `${ODRL}obligation`,
  `${ODRL}duty`, `${ODRL}consequence`,
];

export const CONSTRAINT_PREDS = [`${ODRL}constraint`, `${ODRL}refinement`];

const REALISATION = `${PROV}wasDerivedFrom`;

export interface ReadStore {
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

export interface Anchor { parent: Term; pred: string }

export const termOf = termFromJs as (x: unknown) => Term | null;

function sameTerm(a: Term, b: Term): boolean {
  return a.termType === b.termType && a.value === b.value;
}

export function nodeAnchor(
  store: ReadStore | null, t0: Term | null, preds: string[], preferred?: unknown,
): Anchor | null {
  if (!store || !t0) return null;
  const candidates: Quad[] = [];
  for (const pred of preds) {
    candidates.push(...store.getQuads(null, termOf(pred), t0, null));
  }
  if (!candidates.length) return null;
  const v = termOf(preferred);
  const own = (v && candidates.find((q) => sameTerm(q.subject, v)))
    || (candidates.length === 1 ? candidates[0] : null);
  return own ? { parent: own.subject, pred: own.predicate.value || '' } : null;
}

export function constraintAnchor(
  store: ReadStore | null, cTerm: Term | null, ruleTerm: Term | null,
): Anchor | null {
  if (!store || !cTerm) return null;
  const candidates: Quad[] = [];
  for (const pred of CONSTRAINT_PREDS) {
    candidates.push(...store.getQuads(null, termOf(pred), cTerm, null));
  }
  if (!candidates.length) return null;
  const actions = new Set<string>();
  if (ruleTerm) {
    for (const q of store.getQuads(ruleTerm, termOf(`${ODRL}action`), null, null)) {
      if (q.object.value) actions.add(q.object.value);
    }
  }
  const own = (ruleTerm && candidates.find((q) => sameTerm(q.subject, ruleTerm)))
    || candidates.find((q) => actions.has(q.subject.value || ''))
    || (candidates.length === 1 ? candidates[0] : null);
  return own ? { parent: own.subject, pred: own.predicate.value || '' } : null;
}

export function staysInUse(
  store: ReadStore | null, anchor: Anchor | null, t0: Term | null,
): boolean {
  if (!store || !anchor || !t0) return false;
  const parent = anchor.parent;
  if (!parent || !parent.value) return false;
  return store.getQuads(null, null, t0, null).some((q) => !(
    q.subject.value === parent.value && q.predicate.value === anchor.pred)
    && !sameTerm(q.subject, t0)
    && q.predicate.value !== REALISATION);
}

export function detachQuads(
  store: ReadStore | null, anchor: Anchor | null, t0: Term | null,
  closure: (store: ReadStore, term: Term) => Quad[],
): Quad[] {
  if (!store || !anchor || !t0) return [];
  const link = store.getQuads(anchor.parent, termOf(anchor.pred), t0, null);
  if (!link.length) return [];
  if (staysInUse(store, anchor, t0)) return link;
  return [
    ...link,
    ...store.getQuads(null, termOf(REALISATION), t0, null),
    ...closure(store, t0),
  ];
}
