import { actionState, unlockExplanation } from '../strip.jsx';
import type { IconState } from '../strip.jsx';
import type { Quad, Term } from '../../../model-boundary.js';
import type { Core } from './core.js';

export function editState(core: Core, opts: {
  allow: boolean;
  title?: string;
  action?: (e?: Event) => void;
  term?: Term | null;
  blocked?: Quad[] | null;
  notApplicable?: string;
  unlockable?: boolean;
}): IconState {
  if (opts.allow) return actionState({ allow: true, title: opts.title, action: opts.action });
  const asks = !!(opts.term || (opts.blocked && opts.blocked.length));
  const target = asks && opts.unlockable
    ? core.unlockTarget(opts.term ?? null, opts.blocked ?? null) : null;
  return actionState({
    allow: false,
    title: opts.title,
    notApplicable: opts.notApplicable,
    unlockable: !!target,
    onUnlock: target ? () => { void target.make().catch(() => {}); } : undefined,
    unlockExplanation: target ? unlockExplanation(target) : undefined,
  });
}
