// THE PARTY ROW: [+] and ↻, the same two controls the rest of the edit layer
// speaks. The ↻ is the third caller of `PickList`; the [+] opens the
// IRI-with-a-proposal of the card's own name field, which is also the way to
// type an IRI straight in.
import { createMemo, createSignal, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  addParty, addPartyCollection, expandIri, isPartyCollection, partyOptions,
  partySuggestion, removeProp, setIri, validIriText,
} from '../../model/edit.js';
import type { Term } from '../../model-boundary.js';
import { graph, graphVersion } from '../../stores/corpus.js';
import { text, setNotice } from '../../stores/view.js';
import { termOf } from '../../model/fields.js';
import { focusAddress, requestEditFocus } from '../shared/edit-hook.jsx';
import { core } from './core.js';
import { Button } from './button.jsx';
import { InlineField } from './field.jsx';
import type { FieldHook } from './field.jsx';
import type { FieldSpec } from './hooks.jsx';
import type { IconState } from './strip.jsx';
import { SecIconButton, PlusIcon, ReuseIcon } from './integration/card-edit.jsx';
import { PickList, rank } from './integration/reuse-list.jsx';
import type { Candidate, CandidateRow } from './integration/reuse-list.jsx';
import { closeReuse, openKey, reuseKey, toggleReuse } from './integration/reuse-open.js';
import { showToast } from './toast.jsx';
import './edit.css';

interface ReadStore {
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): {
    object: Term; graph?: { value?: string };
  }[];
}

const asTerm = (t: unknown): Term | null => termOf(t) as Term | null;

const TIER = { sameSource: 0, otherPolicy: 1, loose: 2 };

let cache: { g: unknown; v: number; rows: CandidateRow[] } | null = null;

/** Every party the graph knows, read once per graph version for all rows. */
export function partyCandidates(): CandidateRow[] {
  const g = graph();
  const v = graphVersion();
  if (!g) return [];
  if (!cache || cache.g !== g || cache.v !== v) {
    cache = { g, v, rows: partyOptions(g) as CandidateRow[] };
  }
  return cache.rows;
}

function sourceOf(term: Term | null): string {
  const g = graph() as unknown as ReadStore | null;
  if (!g || !term) return '';
  for (const q of g.getQuads(term, null, null, null)) {
    if (q.graph && q.graph.value) return q.graph.value;
  }
  return '';
}

function valueNode(spec: FieldSpec, pred: string): Term | string | null {
  const g = graph() as unknown as ReadStore | null;
  const t = asTerm(spec.term);
  const own = (g && t && pred) ? g.getQuads(t, asTerm(pred), null, null) : [];
  if (own.length === 1) return own[0].object as Term;
  return spec.iri || null;
}

function isGroupValue(spec: FieldSpec, pred: string): boolean {
  void graphVersion();
  return !!spec.newGroup && !!isPartyCollection(graph(), valueNode(spec, pred));
}

function NewGroupButton(props: { spec: FieldSpec; pred: () => string }): JSX.Element {
  const alreadyGroup = () => isGroupValue(props.spec, props.pred());
  const title = () => text(alreadyGroup() ? 'edit.groupAlreadyGroup' : 'edit.addGroup');
  const make = () => {
    if (alreadyGroup()) return;
    let fresh: unknown = null;
    void core().execute(
      (f) => { fresh = addPartyCollection(f, asTerm(props.spec.term), props.pred()); },
      { group: true },
    )
      .then((ok) => {
        if (!ok) return;
        showToast('edit.groupCreated');
        requestEditFocus(focusAddress(fresh));
      })
      .catch(() => {});
  };
  return (
    <Button
      label={text('edit.groupButton')}
      cls={alreadyGroup() ? 'group-button action-off' : 'group-button'}
      title={title()}
      ariaLabel={title()}
      onClick={make}
    />
  );
}

function linkedIri(term: unknown, pred: string): string | null {
  const g = graph() as unknown as ReadStore | null;
  const t = asTerm(term);
  if (!g || !t || !pred) return null;
  const own = g.getQuads(t, asTerm(pred), null, null);
  if (!own.length) return null;
  const o = own[0].object as Term;
  return o.termType === 'NamedNode' ? (o.value ?? '') : '';
}

export function PartyField(props: {
  spec: FieldSpec; pred: () => string; read: () => JSX.Element;
}): JSX.Element {
  const term = createMemo(() => asTerm(props.spec.term));
  const key = () => reuseKey(term()?.id || term()?.value || '', `party|${props.pred()}`);

  const linked = () => {
    void graphVersion();
    return linkedIri(props.spec.term, props.pred());
  };
  // A named value comes from the card, so the row says what the card says; a
  // blank one (a group without an IRI) is not in the spec and comes from the
  // graph.
  const filled = () => {
    void graphVersion();
    if (props.spec.iri) return true;
    const v = valueNode(props.spec, props.pred());
    return !!v && typeof v !== 'string' && v.termType === 'BlankNode';
  };

  const options = createMemo<CandidateRow[]>(() => {
    void graphVersion();
    const here = linked();
    return partyCandidates().filter((c) => c.iri !== here);
  });

  // The order answers "which of these is probably mine": first what stands in
  // the same source as this policy, then what another policy already names,
  // then what hangs on nothing yet — the register-shaped candidates.
  const ranked = createMemo<Candidate[]>(() => {
    if (openKey() !== key()) return [];
    const mine = sourceOf(term());
    const same = (iri: string) => !!mine
      && sourceOf({ termType: 'NamedNode', value: iri } as Term) === mine;
    return rank(options(), (r) => {
      if (same(r.iri)) return TIER.sameSource;
      return r.provenance.length ? TIER.otherPolicy : TIER.loose;
    });
  });

  // Party candidates always carry an IRI: partyOptions only collects NamedNodes,
  // so there is no blank to promote here.
  const pick = (c: Candidate): void => {
    void core().execute((f) => setIri(f, props.spec.term, props.pred(), c.iri), { group: true })
      .then((ok) => {
        if (!ok) return;
        showToast('edit.partyPicked');
        closeReuse();
      })
      .catch(() => {});
  };

  const [adding, setAdding] = createSignal(false);
  let hook: FieldHook | null = null;
  const proposal = () => {
    void graphVersion();
    return (partySuggestion(graph(), props.spec.term) as string) || '';
  };
  const startAdd = (): void => {
    closeReuse();
    setAdding(true);
    queueMicrotask(() => hook?.openEdit());
  };
  const saveNew = (value: string): void => {
    setAdding(false);
    const iri = expandIri(String(value || '').trim()) as string;
    if (!iri) return;
    if (!validIriText(iri)) {
      setNotice('edit.invalidIri', { input: value });
      return;
    }
    void core().execute((f) => { addParty(f, props.spec.term, props.pred(), iri); },
      { group: true })
      .then((ok) => { if (ok) showToast('edit.partyAdded'); })
      .catch(() => {});
  };

  const unlink = (): void => {
    void core().execute((f) => removeProp(f, props.spec.term, props.pred()), { group: true })
      .then((ok) => { if (ok) showToast('edit.partyRemoved'); })
      .catch(() => {});
  };

  const addState = (): IconState => ({
    on: true, title: text('edit.partyAdd'), action: startAdd,
  });
  const reuseState = (): IconState => (options().length
    ? { on: true, title: text('edit.partyReuse'), action: () => toggleReuse(key()) }
    : { on: false, title: text('edit.partyNone') });

  return (
    <span class="party-field">
      <Show
        when={filled()}
        fallback={<span class="inline-field-hint">{props.spec.hint}</span>}
      >
        <span class="party-link">
          {props.read()}
          <Button
            label="✕"
            cls="party-x"
            title={text('edit.partyRemove')}
            ariaLabel={text('edit.partyRemove')}
            onClick={unlink}
          />
        </span>
      </Show>
      <SecIconButton
        cls="sec-add-btn party-add"
        name={text('edit.partyAdd')}
        state={addState()}
        icon={<PlusIcon />}
      />
      <SecIconButton
        cls="sec-add-btn party-reuse"
        name={text('edit.partyReuse')}
        state={reuseState()}
        icon={<ReuseIcon />}
      />
      <Show when={props.spec.newGroup}>
        <NewGroupButton spec={props.spec} pred={props.pred} />
      </Show>
      <Show when={adding()}>
        <span class="party-new">
          <InlineField
            value=""
            startValue={proposal()}
            hint={text('edit.partyNewHint')}
            withoutPencil
            onSave={saveNew}
            onCancel={() => setAdding(false)}
            hook={(api) => { hook = api; }}
          />
        </span>
      </Show>
      <PickList
        listKey={key}
        candidates={ranked}
        onPick={pick}
        ariaLabel={text('edit.partyChoose')}
        idPrefix="party-pick"
        badge={() => <span class="method ghost-badge">{text('edit.reusePick')}</span>}
        scopeSel=".party-field"
        buttonSel=".party-reuse"
        looseKey="edit.partyLoose"
      />
    </span>
  );
}
